 "content": "from collections import deque


def transform(grid):
    """Slide every same-color 4-connected object right until blocked."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            objects.append((color, cells))

    # Let rightmost objects settle first; repeat to a fixed point so every
    # object travels as far right as the other objects and boundary permit.
    objects.sort(key=lambda obj: max(x for _, x in obj[1]), reverse=True)
    positions = [cells[:] for _, cells in objects]
    moved = True
    while moved:
        moved = False
        for i, ((_, _), cells) in enumerate(zip(objects, positions)):
            occupied = {p for j, other in enumerate(positions) if j != i for p in other}
            if all(x + 1 < w and (y, x + 1) not in occupied for y, x in cells):
                positions[i] = [(y, x + 1) for y, x in cells]
                moved = True

    out = [[0] * w for _ in range(h)]
    for (color, _), cells in zip(objects, positions):
        for r, c in cells:
            out[r][c] = color
    return out
